from dataclasses import dataclass

from aerona.rules.groups import RuleGroup
from aerona.rules.model import rule


@dataclass(frozen=True)
class CoreRulesRules:
    tier_uncommon: int = rule(3, 1, 30, RuleGroup.RARITY_TIERS, "Entity power level: this and above is Uncommon")
    tier_rare: int = rule(5, 1, 30, RuleGroup.RARITY_TIERS, "Entity power level: this and above is Rare")
    tier_epic: int = rule(7, 1, 30, RuleGroup.RARITY_TIERS, "Entity power level: this and above is Epic")
    tier_legendary: int = rule(9, 1, 30, RuleGroup.RARITY_TIERS, "Entity power level: this and above is Legendary")
    tier_mythic: int = rule(11, 1, 30, RuleGroup.RARITY_TIERS, "Entity power level: this and above is Mythic")
    star_level_step: int = rule(2, 1, 10, RuleGroup.RARITY_TIERS, "Star requirement: level needed per star (for \u2605n: n \u00d7 this \u2212 1)")
    star_renown_step: int = rule(15, 0, 100, RuleGroup.RARITY_TIERS, "Star requirement: renown needed per star")
    star_essence_base: int = rule(15, 0, 500, RuleGroup.RARITY_TIERS, "Star requirement: base of the essence cost")
    star_essence_step: int = rule(10, 0, 500, RuleGroup.RARITY_TIERS, "Star requirement: extra essence cost per star")
    stars_per_power_cap: int = rule(2, 1, 10, RuleGroup.RARITY_TIERS, "Every this many stars raises the power cap by 1")
    existence_base: int = rule(25, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Base of a son's existence")
    existence_faith_cap: int = rule(40, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Maximum contribution of faith to existence")
    existence_faith_divisor: int = rule(2, 1, 100, RuleGroup.CREATOR_AND_ESSENCE, "Faith contribution to existence: faith / this number")
    existence_renown_cap: int = rule(25, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Maximum contribution of renown to existence")
    existence_renown_divisor: int = rule(4, 1, 100, RuleGroup.CREATOR_AND_ESSENCE, "Renown contribution to existence: renown / this number")
    existence_anchor_bonus: int = rule(10, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Contribution of a living anchor to existence")
    existence_anchorless_penalty: int = rule(20, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Existence loss of a son whose anchor has been destroyed")
    existence_no_worshipper_penalty: int = rule(15, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Existence loss of a son with no worshippers at all")
    existence_radiant: int = rule(80, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Existence at or above this is Radiant")
    existence_solid: int = rule(30, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Existence at or above this is Solid (below it, one action point less)")
    existence_faded: int = rule(12, 0, 100, RuleGroup.CREATOR_AND_ESSENCE, "Existence at or above this is Faded (below it, cannot act)")
    strength_bonus: int = rule(15, 0, 50, RuleGroup.RARITY_TIERS, "Stat added to a summoned son's strong points")
    weakness_penalty: int = rule(15, 0, 50, RuleGroup.RARITY_TIERS, "Stat subtracted from a summoned son's weak point")
    max_hp_base: int = rule(50, 1, 1000, RuleGroup.GOD_AND_SON_COSTS, "Base of a son's maximum HP")
    max_hp_per_endurance: int = rule(150, 0, 1000, RuleGroup.GOD_AND_SON_COSTS, "Contribution of endurance to maximum HP (% per endurance point)")
    max_essence_base: int = rule(40, 1, 1000, RuleGroup.GOD_AND_SON_COSTS, "Base of a son's maximum essence")
    max_essence_per_might: int = rule(160, 0, 1000, RuleGroup.GOD_AND_SON_COSTS, "Contribution of might to maximum essence (% per might point)")
    default_might: int = rule(20, 0, 100, RuleGroup.GOD_AND_SON_COSTS, "Might assumed for a son whose might is unknown")
    xp_per_level: int = rule(100, 1, 10000, RuleGroup.GOD_AND_SON_COSTS, "XP needed per level for the next level")
    cost_per_power_level: int = rule(3, 0, 50, RuleGroup.GOD_AND_SON_COSTS, "Creation-cost surcharge per power level")
    cost_in_domain_pct: int = rule(60, 1, 500, RuleGroup.GOD_AND_SON_COSTS, "Cost of a creation within one's own domain (%)")
    cost_out_of_domain_pct: int = rule(130, 1, 500, RuleGroup.GOD_AND_SON_COSTS, "Cost of a creation in another domain (%)")
    creativity_discount_pct: int = rule(40, 0, 100, RuleGroup.GOD_AND_SON_COSTS, "Share of creation cost removed by 100 creativity (%)")
    cheap_power_cost_pct: int = rule(60, 1, 100, RuleGroup.GOD_AND_SON_COSTS, "Cost with the cheap-creation power (%)")
    initiative_die: int = rule(20, 1, 100, RuleGroup.GOD_AND_SON_COSTS, "Faces of the initiative die (result is added doubled)")
    relation_blood_enemy: int = rule(70, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or below minus this is blood enemy")
    relation_enemy: int = rule(35, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or below minus this is enemy")
    relation_cold: int = rule(10, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or below minus this is cold")
    relation_friend: int = rule(15, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or above this is friend")
    relation_close_friend: int = rule(45, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or above this is close friend")
    relation_sibling: int = rule(75, 0, 100, RuleGroup.WAR_AND_DIPLOMACY, "God relation at or above this is sibling (brother)")
    tireless_extra_action: int = rule(1, 0, 10, RuleGroup.RARITY_TIERS, 'Extra action granted by the "Tireless" power')
    max_star_extra_action: int = rule(1, 0, 10, RuleGroup.RARITY_TIERS, "Extra action of a son who reaches the highest star (\u26055)")
    faded_action_loss: int = rule(1, 0, 10, RuleGroup.RARITY_TIERS, "Actions lost by a son whose existence falls below the Solid threshold")
    min_actions: int = rule(1, 0, 10, RuleGroup.RARITY_TIERS, "Minimum actions per epoch of a son who has not faded")
